B.zG=new A.J(B.iE6,["; Demonstracao basica: registos, aritmetica e comparacao.\n; Ponto de partida ideal para uma primeira tutoria.\n\nLEDS            EQU     fff8h\n\n                ORIG    0000h\n\nMain:           MOV     R1, 5           ; R1 = 5\n                MOV     R2, 3           ; R2 = 3\n                ADD     R1, R2          ; R1 = R1 + R2   (8)\n                CMP     R1, 8           ; compara R1 com 8, actualiza flags\n                MOV     R3, R1          ; R3 = R1\n                SUB     R3, R2          ; R3 = R3 - R2   (5)\n\n                MOV     M[LEDS], R1     ; mostra R1 (8) nos LEDS\n\nFim:            BR      Fim             ; ciclo infinito, fim do programa\n","; Programa que conta ate ffffh e mostra o resultado em binario nos LEDS.\n\nLEDS            EQU     fff8h\n\n                ORIG    0000h\n\n                JMP     Main\n\nDelay:          MOV     R7, f000h\nDelayInc:       INC     R7\n                BR.NZ   DelayInc\n                RET\n\nMain:           MOV     R1, R0          ; R0 e sempre 0\nLoop:           INC     R1\n                MOV     M[LEDS], R1     ; escreve R1 nos LEDS\n                CALL    Delay\n                BR      Loop\n",";===============================================================================\n;       Modelo vazio (substituir pelo titulo do programa)\n;===============================================================================\n\nINT0_BTN        EQU     fe00h\nINT15_TIMER     EQU     fe0fh\n\nDISP7SEG_0      EQU     fff0h\nDISP7SEG_1      EQU     fff1h\nDISP7SEG_2      EQU     fff2h\nDISP7SEG_3      EQU     fff3h\nLCD_CONTROL     EQU     fff4h\nLCD_WRITE       EQU     fff5h\nTIMER_VALUE     EQU     fff6h\nTIMER_CONTROL   EQU     fff7h\nLEDS            EQU     fff8h\nSWITCHES        EQU     fff9h\nINT_MASK        EQU     fffah\nTERM_CURSOR     EQU     fffch\nTERM_STATE      EQU     fffdh\nTERM_WRITE      EQU     fffeh\nTERM_READ       EQU     ffffh\n\nSP_ADDRESS      EQU     fdffh\n\n                ORIG    8000h\n\nA_VARIABLE      WORD    1010011010b\nA_STRING        STR     'Uma String', ' mais palavras', '!', 0000h\n\n                ORIG    0000h\n                JMP     Main\n\nMain:           MOV     R1, SP_ADDRESS\n                MOV     SP, R1          ; inicializa o stack pointer\n\n                MOV     R1, SWITCHES\n                MOV     R2, M[R1]       ; le os interruptores\n                MOV     M[LEDS], R2     ; mostra nos LEDS\n\nFim:            BR      Fim\n"],t.w)
